insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-30','verbeterd','Projectbezoek','Meerdere foto''s per punt, ook uit je galerij',
   'Bij een projectbezoek kun je nu naast "Foto maken" ook "Uit galerij" kiezen en daar meerdere foto''s tegelijk selecteren. Foto''s kun je meteen bij een nieuw punt kiezen; ze worden samen met het punt opgeslagen. Handig als je eerst rondloopt en fotografeert, en de punten daarna vastlegt.');
